50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
54	const ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	/** What the MHPCO knows about a kind of item it will insure: what insuring
60	 *  one costs (`basePremium`), and what one is insured FOR (`insuranceValue`,
61	 *  from which the cap is derived — never from premiums). One entry per kind,
62	 *  so the two figures for a kind cannot drift apart. */
63	interface ItemKind {
64	  basePremium: number;
65	  insuranceValue: number;
66	}
67	
68	/** The MHPCO's price list. */
69	const ITEM_KINDS: Record<string, ItemKind> = {
70	  sword: { basePremium: 100, insuranceValue: 1000 },
71	  amulet: { basePremium: 60, insuranceValue: 600 },
72	  staff: { basePremium: 80, insuranceValue: 800 },
73	  potion: { basePremium: 40, insuranceValue: 400 },
74	  rune: { basePremium: 25, insuranceValue: 250 },
75	  moonstone: { basePremium: 25, insuranceValue: 250 },
76	};
77	
78	/** The price list entry for a type. The MHPCO insures only what its price
79	 *  list names, so an unlisted type is rejected rather than priced. */
80	const itemKindOf = (type: string): ItemKind => {
81	  const kind = ITEM_KINDS[type];
82	  if (kind === undefined) {
83	    throw new Error(`unknown item type: ${type}`);
84	  }
85	  return kind;
86	};
87	
88	/** What insuring this item costs, before any modifier. */
89	const basePremiumOf = (item: Item): number => itemKindOf(item.type).basePremium;
90	
91	/** What this item is insured FOR — the figure the cap derives from. Unmodified
92	 *  by anything that moves the premium: a curse costs more to insure without
93	 *  making the sword worth more. */
94	const insuranceValueOf = (item: Item): number =>
95	  itemKindOf(item.type).insuranceValue;
96	
97	const DEDUCTIBLE_PER_DAMAGED_ITEM = 100;
98	const CAP_MULTIPLE = 2;
99	
100	/** The enchantment level from which a CLAIM is only half reimbursed. A claim
101	 *  rule, unrelated to ENCHANTMENT_SURCHARGE_LEVEL, which gates a premium
102	 *  surcharge — the two thresholds differ and move independently. */
103	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
104	const HALF_REIMBURSEMENT_PERCENT = 50;
105	
106	/** Modifiers are expressed as an amount to add, never as a factor to multiply
107	 *  by, so that they stay additive against their base and so that the integer
108	 *  numerator keeps float artifacts out of the final rounding
109	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
110	const percentOf = (amount: number, percent: number): number =>
111	  (amount * percent) / 100;
112	
113	/** Rounds up — premiums round in the MHPCO's favour. */
114	const roundPremium = (amount: number): number => Math.ceil(amount);
115	
116	/** Rounds down — payouts, too, round in the MHPCO's favour. */
117	const roundPayout = (amount: number): number => Math.floor(amount);
118	
119	const COMPONENT_BLOCK_SIZE = 3;
120	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
121	
122	const COMPONENT_TYPES = ["rune", "moonstone"];
123	
124	const isComponent = (item: Item): boolean =>
125	  COMPONENT_TYPES.includes(item.type);
126	
127	/** How many of each kind, for whatever "kind" means to the caller. Quotes
128	 *  tally insured items by their type; claims tally damage entries by the type
129	 *  they name — one notion of counting, two things counted. */
130	const countBy = <T>(values: T[], keyOf: (value: T) => string) => {
131	  const counts = new Map<string, number>();
132	  for (const value of values) {
133	    const key = keyOf(value);
134	    counts.set(key, (counts.get(key) ?? 0) + 1);
135	  }
136	  return counts;
137	};
138	
139	const typeOfItem = (item: Item): string => item.type;
140	const typeOfDamage = (damage: Damage): string => damage.itemType;
141	
142	/** A block is exactly three alike components, priced as a unit rather than
143	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
144	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
145	  count === COMPONENT_BLOCK_SIZE
146	    ? COMPONENT_BLOCK_BASE_PREMIUM
147	    : count * itemKindOf(type).basePremium;
148	
149	const sum = (amounts: number[]): number =>
150	  amounts.reduce((total, amount) => total + amount, 0);
151	
152	const policyBasePremium = (items: Item[]): number => {
153	  const mainItems = items.filter((item) => !isComponent(item));
154	  const componentGroups = [...countBy(items.filter(isComponent), typeOfItem)];
155	
156	  return (
157	    sum(mainItems.map(basePremiumOf)) +
158	    sum(componentGroups.map(componentGroupBasePremium))
159	  );
160	};
161	
162	interface ItemModifierRule {
163	  appliesTo: (item: Item) => boolean;
164	  percent: number;
165	}
166	
167	/** Every item-scoped modifier, as a rule that either applies to an item or
168	 *  does not. Applicable rules stack. */
169	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
170	  {
171	    appliesTo: (item) => item.cursed === true,
172	    percent: CURSE_SURCHARGE_PERCENT,
173	  },
174	  {
175	    appliesTo: (item) => (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL,
176	    percent: ENCHANTMENT_SURCHARGE_PERCENT,
177	  },
178	];
179	
180	/** Item-scoped modifiers apply to the affected item's own base premium,
181	 *  not to the policy total. */
182	const itemModifierAmount = (item: Item): number =>
183	  sum(
184	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
185	      percentOf(basePremiumOf(item), rule.percent),
186	    ),
187	  );
188	
189	/** A policy written by a quote step, as later claim steps see it. The insured
190	 *  items are kept because a damage entry names only a type, while the clauses
191	 *  that govern its reimbursement depend on the insured item itself. */
192	interface Policy {
193	  remainingCap: number;
194	  items: Item[];
195	}
196	
197	/** What a step leaves behind for the steps after it. Steps are not
198	 *  independent: a quote is priced against how many contracts precede it, and
199	 *  a claim is paid against a policy an earlier quote wrote, so running a
200	 *  scenario threads this state from each step to the next. */
201	interface ScenarioState {
202	  customer: Customer;
203	  precedingContracts: number;
204	  /** Keyed by the zero-based index of the quote step that wrote the policy —
205	   *  which is what a claim step's `policy` field refers to. */
206	  policiesByStep: Record<number, Policy>;
207	}
208	
209	const initialState = (customer: Customer): ScenarioState => ({
210	  customer,
211	  precedingContracts: 0,
212	  policiesByStep: {},
213	});
214	
215	/** A step's outcome: what it reports, and the state the next step sees. */
216	interface StepOutcome {
217	  result: StepResult;
218	  state: ScenarioState;
219	}
220	
221	/** What a policy-wide rule may look at: the customer, plus where this quote
222	 *  sits in the customer's history of contracts. A pricing view of the
223	 *  scenario state — rules read it, they never advance it. */
224	type PolicyContext = Readonly<ScenarioState>;
225	
226	interface PolicyModifierRule {
227	  appliesTo: (context: PolicyContext) => boolean;
228	  /** Signed: positive surcharges, negative discounts. */
229	  percent: number;
230	}
231	
232	/** Every policy-wide modifier, as a rule that either applies to a policy or
233	 *  does not. Applicable rules stack. */
234	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
235	  {
236	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
237	    percent: -LOYALTY_DISCOUNT_PERCENT,
238	  },
239	  {
240	    appliesTo: () => true,
241	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
242	  },
243	  {
244	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
245	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
246	  },
247	];
248	
249	/** Policy-wide modifiers apply to the policy base premium — the sum of every
250	 *  item's base premium — not to any single item. */
251	const policyModifierAmount = (
252	  basePremium: number,
253	  context: PolicyContext,
254	): number =>
255	  sum(
256	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
257	      (rule) => percentOf(basePremium, rule.percent),
258	    ),
259	  );
260	
261	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
262	  const basePremium = policyBasePremium(items);
263	  // Every modifier is an amount added to the base premium, not a factor
264	  // compounded onto a running total: item-scoped modifiers take a percentage
265	  // of their own item's base premium, policy-wide ones take a percentage of
266	  // the policy base premium.
267	  const modifierAmounts = [
268	    ...items.map(itemModifierAmount),
269	    policyModifierAmount(basePremium, context),
270	  ];
271	  // The processing fee is added last, after all percentage modifiers.
272	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
273	  return { premium: roundPremium(premium) };
274	};
275	
276	/** The cap on everything a policy will ever pay out: twice the sum of the
277	 *  insured items' values. Premium modifiers do not raise it. */
278	const policyCap = (items: Item[]): number =>
279	  CAP_MULTIPLE * sum(items.map(insuranceValueOf));
280	
281	/** What one damage entry reimburses before the deductible: the full damage,
282	 *  unless a special clause reduces it. */
283	const reimbursableAmount = (damage: Damage, insuredItem: Item): number =>
284	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
285	    ? percentOf(damage.amount, HALF_REIMBURSEMENT_PERCENT)
286	    : damage.amount;
287	
288	/** The insured item a damage entry refers to. A damage entry names only a
289	 *  type, while the clauses governing its reimbursement depend on the item.
290	 *  The MHPCO pays only for what it insured, so a damage entry naming a type
291	 *  the policy does not cover is rejected rather than reimbursed. */
292	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
293	  const insuredItem = policy.items.find(
294	    (item) => item.type === damage.itemType,
295	  );
296	  if (insuredItem === undefined) {
297	    throw new Error(`damaged item is not insured: ${damage.itemType}`);
298	  }
299	  return insuredItem;
300	};
301	
302	/** A damage entry states what an incident cost. An amount below zero states
303	 *  that the incident paid the claimant, which is not a thing an incident can
304	 *  do — so it is rejected as malformed rather than reimbursed. Zero is a
305	 *  well-formed claim for nothing, and passes. */
306	const rejectNegativeDamageAmount = (damage: Damage): void => {
307	  if (damage.amount < 0) {
308	    throw new Error(`damage amount must not be negative: ${damage.amount}`);
309	  }
310	};
311	
312	/** What one damage entry claims: the reimbursable amount, less the deductible
313	 *  that is charged once per damaged item. Not yet what the policy pays — the
314	 *  cap applies to the incident total, not to any single entry, and rounding
315	 *  comes later still, so this figure stays fractional. */
316	const claimedForDamage = (damage: Damage, policy: Policy): number => {
317	  rejectNegativeDamageAmount(damage);
318	  return (
319	    reimbursableAmount(damage, insuredItemFor(damage, policy)) -
320	    DEDUCTIBLE_PER_DAMAGED_ITEM
321	  );
322	};
323	
324	/** The state that results from recording one policy against a step index,
325	 *  replacing any policy already recorded there. */
326	const withPolicy = (
327	  state: ScenarioState,
328	  stepIndex: number,
329	  policy: Policy,
330	): ScenarioState => ({
331	  ...state,
332	  policiesByStep: { ...state.policiesByStep, [stepIndex]: policy },
333	});
334	
335	/** Writes a policy, and records it so later claim steps can be paid against
336	 *  it. Each quote written also becomes a preceding contract for the next. */
337	const runQuote = (
338	  step: QuoteStep,
339	  stepIndex: number,
340	  state: ScenarioState,
341	): StepOutcome => ({
342	  result: quote(step.items, state),
343	  state: withPolicy(
344	    { ...state, precedingContracts: state.precedingContracts + 1 },
345	    stepIndex,
346	    { remainingCap: policyCap(step.items), items: step.items },
347	  ),
348	});
349	
350	/** The MHPCO insures items, not types: a policy covering one sword answers
351	 *  for one damaged sword. More entries of a type than the policy covers
352	 *  rejects the whole claim, not merely the surplus entry. */
353	const rejectMoreDamagesThanInsuredItems = (
354	  damages: Damage[],
355	  policy: Policy,
356	): void => {
357	  const insuredCounts = countBy(policy.items, typeOfItem);
358	  const overclaimed = [...countBy(damages, typeOfDamage)].find(
359	    ([type, claimed]) => claimed > (insuredCounts.get(type) ?? 0),
360	  );
361	  if (overclaimed !== undefined) {
362	    throw new Error(
363	      `more damage entries than insured items of type: ${overclaimed[0]}`,
364	    );
365	  }
366	};
367	
368	/** What an incident claims in total, before the policy's cap is applied:
369	 *  every damage entry reimbursed on its own terms, less its own deductible. */
370	const claimedAmount = (damages: Damage[], policy: Policy): number => {
371	  rejectMoreDamagesThanInsuredItems(damages, policy);
372	  return sum(damages.map((damage) => claimedForDamage(damage, policy)));
373	};
374	
375	/** A policy never pays out more than the cap it has left, so a claim that
376	 *  exhausts the cap is paid down to it rather than past it. */
377	const paidWithinCap = (claimed: number, remainingCap: number): number =>
378	  Math.min(claimed, remainingCap);
379	
380	/** What a policy actually hands over for one incident: what the incident
381	 *  claims, held to what the cap has left, and only then rounded. Rounding
382	 *  last is what keeps the intermediates fractional — a half-reimbursed
383	 *  damage stays at 450.5 until the whole payout is settled. */
384	const payoutFor = (damages: Damage[], policy: Policy): number =>
385	  roundPayout(
386	    paidWithinCap(claimedAmount(damages, policy), policy.remainingCap),
387	  );
388	
389	/** The policy a claim step is claiming against. A claim names a policy by the
390	 *  index of the quote step that wrote it, so an index no quote step wrote — or
391	 *  one naming a later step, or another claim — has no policy to pay from and
392	 *  is rejected rather than dereferenced. */
393	const policyClaimedAgainst = (
394	  step: ClaimStep,
395	  state: ScenarioState,
396	): Policy => {
397	  const policy = state.policiesByStep[step.policy];
398	  if (policy === undefined) {
399	    throw new Error(`no policy written by step: ${step.policy}`);
400	  }
401	  return policy;
402	};
403	
404	/** Pays a claim against the policy an earlier quote step wrote, drawing the
405	 *  payout down from that policy's remaining cap. */
406	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
407	  const policy = policyClaimedAgainst(step, state);
408	  const payout = payoutFor(step.incident.damages, policy);
409	  const remainingCap = policy.remainingCap - payout;
410	  return {
411	    result: { payout, remainingCap },
412	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
413	  };
414	};
415	
416	const runStep = (
417	  step: Step,
418	  stepIndex: number,
419	  state: ScenarioState,
420	): StepOutcome =>
421	  step.op === "quote"
422	    ? runQuote(step, stepIndex, state)
423	    : runClaim(step, state);
424	
425	export const runScenario = (scenario: Scenario): ScenarioResult => {
426	  const { results } = scenario.steps.reduce(
427	    ({ results, state }, step, stepIndex) => {
428	      const outcome = runStep(step, stepIndex, state);
429	      return { results: [...results, outcome.result], state: outcome.state };
430	    },
431	    { results: [] as StepResult[], state: initialState(scenario.customer) },
432	  );
433	  return { results };
434	};
